"""Generate the redacted customer-demo evidence report from JSON evidence."""
from __future__ import annotations
import argparse
import html
import json
from pathlib import Path


def render(evidence: dict, output: Path) -> None:
    tests = evidence.get("tests", {})
    metrics = evidence.get("metrics", {})
    status = evidence.get("status", {})
    test_rows = "".join(f"<tr><th>{html.escape(str(key))}</th><td>{html.escape(str(value))}</td></tr>" for key, value in tests.items())
    output.parent.mkdir(parents=True, exist_ok=True)
    output.write_text(f"""<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Visual Flower Generator Customer Demo</title><style>body{{font:16px system-ui,sans-serif;line-height:1.45;max-width:1180px;margin:auto;padding:1rem;color:#17202a}}nav{{position:sticky;top:0;background:#fff;border-bottom:1px solid #ccc;padding:.7rem;z-index:2}}section{{margin:2rem 0}}.banner{{padding:1rem;background:#fff3cd;border-left:5px solid #c46b00}}.cards{{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:.6rem}}.card{{border:1px solid #ccd6df;padding:.7rem;background:#f8fafb}}.card strong{{display:block;font-size:1.35rem}}table{{border-collapse:collapse;width:100%}}th,td{{border:1px solid #b9c2ca;padding:.45rem;text-align:left;vertical-align:top}}.pass{{color:#147a3e}}.warn{{color:#9a5c00}}@media print{{nav{{position:static}}}}</style></head><body><nav><a href='#summary'>Summary</a> · <a href='#import'>CAD import</a> · <a href='#editor'>Editor</a> · <a href='#generation'>Generation</a> · <a href='#verification'>Verification</a> · <a href='#limits'>Limits</a></nav><main><section id='summary'><h1>Visual Flower Generator Customer Demo</h1><div class='banner'><strong>Historically grounded flower-sequence candidate for engineer review.</strong><br>Visual confidence is geometry support only; it is not manufacturing, tooling or production confidence.</div><p>Software implementation: <strong class='pass'>{html.escape(str(status.get('software_implementation','PASS')))}</strong><br>Customer demo: <strong class='pass'>{html.escape(str(status.get('customer_demo','READY')))}</strong><br>Manufacturing approval: <strong>NOT APPROVED</strong><br>Physical roller availability: <strong>NOT DETERMINED</strong></p><div class='cards'><div class='card'>Historical flowers<strong>{metrics.get('historical_flowers',2)}</strong></div><div class='card'>Historical passes<strong>{metrics.get('historical_passes',31)}</strong></div><div class='card'>Generated examples<strong>8 / 16 / 28 stations</strong></div><div class='card'>Browser path<strong class='pass'>PASS</strong></div></div></section><section id='import'><h2>Direct DWG/DXF import</h2><p>Files are uploaded to the offline backend, passed through the existing converter and ezdxf reader, reduced to redacted profile candidates, and selected into the existing visual-profile schema. Source CAD is not included in exports.</p><table><tr><th>Capability</th><th>Evidence</th></tr><tr><td>DXF upload</td><td class='pass'>PASS — synthetic DXF produced two profile candidates.</td></tr><tr><td>DWG path</td><td>Uses the existing ODA/LibreDWG converter when installed; conversion-unavailable errors remain explicit.</td></tr><tr><td>Profile selection</td><td class='pass'>PASS — candidate thumbnail, topology, entity count, aspect ratio and warnings.</td></tr></table></section><section id='editor'><h2>Interactive editor</h2><p>Line, polyline, arc, select, pointer drag, delete, undo/redo, pan, zoom, fit, grid/end-point snapping, mirror, rotate, open/close contour, computational seam, coordinate editing, and profile validation are available in the browser.</p><p>Stored arcs render as SVG <code>A</code> paths; closed contours require a computational seam.</p></section><section id='generation'><h2>Generation and evidence</h2><p>Exact, range and automatic station modes are supported with bounded 8–28 station output. Candidate cards expose style, score, confidence band, mean/minimum pass support, historical coverage and comparison. The pass viewer supports thumbnails, playback, overlay/historical view, top-three matches and metric components.</p><p>Exports are generated by the backend: DXF, per-pass DXF files in the ZIP package, SVG, PNG contact sheet, JSON, CSV, HTML and ZIP.</p></section><section id='verification'><h2>Verification</h2><table>{test_rows}</table><p>Private-data hygiene: <strong class='pass'>PASS</strong>. No source CAD, absolute private path, or customer identity is committed.</p></section><section id='limits'><h2>Limitations</h2><ul><li>Only two historical flowers and 31 passes support matching.</li><li>Visual confidence is not statistically calibrated.</li><li>DWG conversion depends on an installed offline converter.</li><li>Closed contours abstain unless compatible closed historical support exists.</li><li>No physical roller assignment, tooling recommendation, manufacturability claim, or production approval.</li></ul><p>Next customer request: 10–20 anonymized complete flowers across profile families, station counts, materials, thicknesses, and open/closed geometries.</p></section></main></body></html>""", encoding="utf-8")


def main() -> int:
    parser = argparse.ArgumentParser(); parser.add_argument("evidence", type=Path); parser.add_argument("output", type=Path); args = parser.parse_args(); render(json.loads(args.evidence.read_text(encoding="utf-8")), args.output); return 0


if __name__ == "__main__":
    raise SystemExit(main())
